      var L = legendMetrics(chart, ctx);
      rects.push({ x0: L.x - 3, x1: L.x + L.w + 3, y0: L.y - 3, y1: L.y + L.h + 3 });

      // candidate A: directly above the selected pair (empty by construction)
      var bx = Math.min(Math.max(xm - bw / 2, ca.left + 4), ca.right - bw - 4);
      var topOfPair = Math.min(m0.y, m1.y, zero);
      var by = topOfPair - fs * 1.5 - bh;
      var leader = true;
      var boxA = { x0: bx - 2, x1: bx + bw + 2, y0: by - 2, y1: by + bh + 2 };
      if (by < ca.top + 4 || hits(boxA, rects)) {
        // candidate B: free space just under the legend (short C1–C6 bars)
        leader = false;
        bx = ca.left + L.pad;
        by = L.y + L.h + L.pad * 0.9;
        var boxB = { x0: bx - 2, x1: bx + bw + 2, y0: by - 2, y1: by + bh + 2 };
        if (hits(boxB, rects)) {                    // last resort: top-right corner
          bx = ca.right - bw - L.pad;
          by = ca.top + L.pad;
        }
      }

      if (leader) {
        ctx.strokeStyle = '#555'; ctx.lineWidth = lw;
        ctx.beginPath();
        ctx.moveTo(xm, by + bh); ctx.lineTo(xm, topOfPair - fs * 0.3); ctx.stroke();
        ctx.fillStyle = '#555';
        ctx.beginPath(); ctx.arc(xm, topOfPair - fs * 0.3, lw * 1.6, 0, Math.PI * 2); ctx.fill();
      }
      ctx.fillStyle = 'rgba(255,255,255,0.96)';
      ctx.strokeStyle = '#2b2b2b';
      ctx.lineWidth = lw;
      roundRect(ctx, bx, by, bw, bh, fs * 0.4);
      ctx.fill(); ctx.stroke();
      ctx.textBaseline = 'top';
      for (var j = 0; j < lines.length; j++) {
        ctx.fillStyle = j === 0 ? '#111' : '#333';
        ctx.font = (j === 0 ? '600 ' : '') + fs + 'px sans-serif';
        ctx.fillText(lines[j], bx + padB, by + padB * 0.7 + j * fs * 1.3);
      }
      ctx.restore();
    }
  };

  function tickFont(c) {
    var s = Math.min(c.chart.width, c.chart.height);
    return { size: Math.max(9, Math.min(16, s / 30)) };
  }
  function titleFont(c) {
    var s = Math.min(c.chart.width, c.chart.height);
    return { size: Math.max(10, Math.min(17, s / 28)) };
  }

  var chart = new Chart(canvas.getContext('2d'), {
    type: 'bar',
    data: {
      labels: LABELS,
      datasets: [
        {
          label: 'Melting point', data: MP,
          backgroundColor: function () { return mpColor(); },
          borderColor: '#111',
          borderWidth: function (c) {
            return (userInteracted && c.dataIndex === selected - 1) ? 2 : 0;
          },
          categoryPercentage: 0.8, barPercentage: 0.88
        },
        {
          label: 'Boiling point', data: BP,
          backgroundColor: function () { return bpColor(); },
          borderColor: '#111',
          borderWidth: function (c) {
            return (userInteracted && c.dataIndex === selected - 1) ? 2 : 0;
          },
          categoryPercentage: 0.8, barPercentage: 0.88
        }
      ]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      animation: { duration: 300 },
      layout: { padding: { top: 6, right: 10 } },
      plugins: { legend: { display: false }, tooltip: { enabled: false } },
      scales: {
        x: {
          grid: { display: false, drawTicks: true, tickColor: '#000', tickLength: 5 },
          border: { color: '#000', width: 1.6 },
          ticks: { color: '#111', font: tickFont },
          title: { display: true, text: 'Number of carbons', color: '#111', font: titleFont }
        },
        y: {
          min: -200, max: 300,
          grid: {
            color: function (c) { return (c.tick && c.tick.value === 0) ? '#8a949b' : '#b9c3ca'; },
            lineWidth: function (c) { return (c.tick && c.tick.value === 0) ? 1.6 : 1; },
            drawTicks: true, tickColor: '#000', tickLength: 5
          },
          border: { color: '#000', width: 1.6 },
          ticks: {
            stepSize: 100, color: '#111', font: tickFont,
            callback: function (v) { return v < 0 ? '\u2212' + Math.abs(v) : String(v); }
          },
          title: { display: true, text: 'Temperature (\u00b0C)', color: '#111', font: titleFont }
        }
      }
    },
    plugins: [bgPlugin, legendPlugin, calloutPlugin]
  });
  window.__markRendered();

  document.addEventListener('fig-resize', function () { chart.resize(); });

  // ── hover + click ────────────────────────────────────────────────────────
  canvas.addEventListener('mousemove', function (ev) {
    var els = chart.getElementsAtEventForMode(ev, 'nearest', { intersect: true }, false);
    if (els.length) {
      var e = els[0], i = e.index, d = e.datasetIndex;
      var v = d === 0 ? MP[i] : BP[i];
      canvas.style.cursor = 'pointer';
      showTooltip((d === 0 ? 'Melting' : 'Boiling') + ' point of ' + NAMES[i] +
        ' (C' + (i + 1) + '): ' + fmt(v) + ' \u00b0C', ev);
    } else { canvas.style.cursor = 'default'; hideTooltip(); }
  });
  canvas.addEventListener('mouseleave', hideTooltip);
  canvas.addEventListener('click', function (ev) {
    var els = chart.getElementsAtEventForMode(ev, 'nearest', { intersect: true }, false);
    if (!els.length) return;
    var i = els[0].index;
    document.getElementById('carbonCountInput').value = i + 1;
    document.getElementById('carbonCountVal').value = i + 1;
    update_carbonCount(i + 1);
    var gap = Math.round(BP[i] - MP[i]);
    showPopup(NAMES[i].charAt(0).toUpperCase() + NAMES[i].slice(1) + ' (C' + (i + 1) + ')',
      'Melting point ' + fmt(MP[i]) + ' \u00b0C, boiling point ' + fmt(BP[i]) + ' \u00b0C, a liquid range of about ' +
      gap + ' \u00b0C. A chain of ' + (i + 1) + ' carbons presents more surface area than its shorter neighbours, so London dispersion forces between molecules are stronger and more thermal energy is needed to separate them. ' +
      'Boiling always demands full separation of molecules, so it costs more energy than merely loosening a crystal lattice — the magenta bar stays above the blue one at every chain length.');
  });

  // ── controls ─────────────────────────────────────────────────────────────
  function refreshReadout() {
    var i = selected - 1;
    document.getElementById('readoutUI').innerHTML =
      '<b>C' + selected + ' (' + NAMES[i] + ')</b><br>mp ' + fmt(MP[i]) + ' \u00b0C &nbsp; bp ' +
      fmt(BP[i]) + ' \u00b0C<br>liquid range \u0394 = ' + fmt(BP[i] - MP[i]) + ' \u00b0C';
  }

  window.update_carbonCount = function (v) {
    selected = v;
    userInteracted = true;
    refreshReadout();
    chart.update();
  };
  window.toggle_propertyEmphasis = function (val) {
    emphasis = val;
    chart.update();
  };
  window.showInsight = function () {
    showPopup('Key idea',
      'Every CH\u2082 you add to the chain adds more surface for dispersion forces, so both transition temperatures rise monotonically. ' +
      'The boiling point rises faster and always stays above the melting point, crossing 0 \u00b0C at a much shorter chain (C4\u2013C5) than the melting point does (about C14). ' +
      'That widening blue-to-magenta gap is the growing liquid range of the alkane.');
  };

  // ── demo step player ─────────────────────────────────────────────────────
  var steps = [
    { title: 'The smallest alkane', narration: 'At one carbon (methane) both bars plunge far below zero, near \u2212180 \u00b0C. With so little surface area, dispersion forces are tiny and the molecule stays a gas at any ordinary temperature.', state: { carbonCount: 1, propertyEmphasis: 'Both' } },
    { title: 'Boiling points climb first', narration: 'Follow the magenta series alone: it rises sharply and crosses 0 \u00b0C around four to five carbons, which is why butane is a gas but pentane is a liquid at room temperature.', state: { carbonCount: 5, propertyEmphasis: 'Boiling point' } },
    { title: 'Melting points lag far behind', narration: 'Now emphasize the blue series. Even at ten carbons the melting point is still about \u221230 \u00b0C, so these alkanes are liquids: they have boiled-off neighbours but have not yet become solids.', state: { carbonCount: 10, propertyEmphasis: 'Melting point' } },
    { title: 'The widening gap', narration: 'With both series shown at fourteen carbons, the magenta bar reaches about 250 \u00b0C while the blue bar has only just crossed zero. Each added CH\u2082 raises the boiling point far more than the melting point, so the liquid range keeps expanding.', state: { carbonCount: 14, propertyEmphasis: 'Both' } }
  ];
  var step = 0;
  function applyStep(i) {
    step = (i % steps.length + steps.length) % steps.length;
    var s = steps[step];
    document.getElementById('carbonCountInput').value = s.state.carbonCount;
    document.getElementById('carbonCountVal').value = s.state.carbonCount;
    selected = s.state.carbonCount;
    refreshReadout();
    document.getElementById('propertyEmphasisInput').value = s.state.propertyEmphasis;
    emphasis = s.state.propertyEmphasis;
    userInteracted = (step !== 0);   // step 0 = clean, source-faithful view
    chart.update();
    document.getElementById('demoNarration').textContent = s.narration;
    document.getElementById('stepLabel').textContent =
      'Step ' + (step + 1) + '/' + steps.length + ' \u2014 ' + s.title;
  }
  window.nextStep = function () { applyStep(step + 1); };
  window.prevStep = function () { applyStep(step - 1); };

  applyStep(0);
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using Chart.js.

CONCEPT: Both melting and boiling points of straight-chain alkanes rise steadily with the number of carbons because larger molecules have more surface area and therefore stronger dispersion forces, with boiling points always higher than melting points.
KEY INSIGHT (what students should walk away understanding): Every CH2 you add to the chain adds more surface for dispersion forces, so both transition temperatures rise monotonically — but boiling point rises faster, always staying above melting point and crossing 0 °C at a much shorter chain.
DEMO STEPS: 4 guided steps — implement the step player in #ui

FULL BLUEPRINT:
