// @FIGURE_CODE_BEGIN
(function () {
  var MP = [-182, -183, -190, -138, -130, -95, -91, -57, -51, -30, -26, -10, -6, 5.5];
  var BP = [-164, -89, -42, -0.5, 36, 69, 98, 126, 151, 174, 196, 216, 235, 254];
  var NAMES = ['methane', 'ethane', 'propane', 'butane', 'pentane', 'hexane', 'heptane',
    'octane', 'nonane', 'decane', 'undecane', 'dodecane', 'tridecane', 'tetradecane'];
  var LABELS = [];
  for (var i = 1; i <= 14; i++) LABELS.push(String(i));

  var BLUE = '#1379b7', BLUE_F = '#bcdcf1';
  var MAG = '#c41d6c', MAG_F = '#eec4d8';
  var FIELD = '#dcedfa';

  var selected = 1;
  var emphasis = 'Both';
  var userInteracted = false;   // step-0 render must match the static source exactly

  function fmt(v) {
    var s = (Math.abs(v) < 1 && v !== 0) ? v.toFixed(1) : String(Math.round(v * 10) / 10);
    return (v < 0) ? '\u2212' + s.replace('-', '') : s;
  }

  var container = document.getElementById('container');
  var canvas = document.createElement('canvas');
  canvas.style.cssText = 'width:100%;height:100%;display:block';
  container.appendChild(canvas);

  function mpColor() { return emphasis === 'Boiling point' ? BLUE_F : BLUE; }
  function bpColor() { return emphasis === 'Melting point' ? MAG_F : MAG; }

  // ── pale blue plotting field, drawn BEFORE the scales so gridlines sit on top ──
  var bgPlugin = {
    id: 'fieldBg',
    beforeDraw: function (chart) {
      var ca = chart.chartArea;
      if (!ca) return;
      var ctx = chart.ctx;
      ctx.save();
      ctx.fillStyle = FIELD;
      ctx.fillRect(ca.left, ca.top, ca.width, ca.height);
      ctx.restore();
    }
  };

  function roundRect(ctx, x, y, w, h, r) {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y); ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r); ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h); ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r); ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  }

  function legendMetrics(chart, ctx) {
    var ca = chart.chartArea;
    var S = Math.min(ca.width, ca.height);
    var fs = Math.max(9, Math.min(17, S / 22));
    var sq = fs * 1.15;
    var pad = Math.max(6, S * 0.035);
    ctx.save(); ctx.font = fs + 'px sans-serif';
    var tw = Math.max(ctx.measureText('Melting point').width, ctx.measureText('Boiling point').width);
    ctx.restore();
    return {
      fs: fs, sq: sq, pad: pad,
      x: ca.left + pad, y: ca.top + pad,
      w: sq + fs * 0.55 + tw, h: 2 * sq + fs * 0.55
    };
  }

  var legendPlugin = {
    id: 'innerLegend',
    afterDatasetsDraw: function (chart) {
      var ctx = chart.ctx, L = legendMetrics(chart, ctx);
      var rows = [[mpColor(), 'Melting point'], [bpColor(), 'Boiling point']];
      ctx.save();
      ctx.font = L.fs + 'px sans-serif';
      ctx.textBaseline = 'middle';
      for (var k = 0; k < rows.length; k++) {
        var ry = L.y + k * (L.sq + L.fs * 0.55);
        ctx.fillStyle = rows[k][0];
        ctx.fillRect(L.x, ry, L.sq, L.sq);
        ctx.fillStyle = '#1a1a1a';
        ctx.strokeStyle = '#fff'; ctx.lineWidth = 3; ctx.lineJoin = 'round';
        ctx.strokeText(rows[k][1], L.x + L.sq + L.fs * 0.55, ry + L.sq / 2);
        ctx.fillText(rows[k][1], L.x + L.sq + L.fs * 0.55, ry + L.sq / 2);
      }
      ctx.restore();
    }
  };

  function barRects(chart) {
    var out = [];
    for (var d = 0; d < 2; d++) {
      var arr = chart.getDatasetMeta(d).data;
      for (var i = 0; i < arr.length; i++) {
        var b = arr[i];
        var w = b.width || 6;
        out.push({
          x0: b.x - w / 2, x1: b.x + w / 2,
          y0: Math.min(b.y, b.base), y1: Math.max(b.y, b.base)
        });
      }
    }
    return out;
  }
  function hits(box, rects) {
    for (var i = 0; i < rects.length; i++) {
      var r = rects[i];
      if (box.x0 < r.x1 && box.x1 > r.x0 && box.y0 < r.y1 && box.y1 > r.y0) return true;
    }
    return false;
  }

  // ── selection outline + readout callout (only after user interaction) ────
  var calloutPlugin = {
    id: 'callout',
    afterDatasetsDraw: function (chart) {
      if (!userInteracted) return;
      var ca = chart.chartArea, ctx = chart.ctx;
      var i = selected - 1;
      var m0 = chart.getDatasetMeta(0).data[i], m1 = chart.getDatasetMeta(1).data[i];
      if (!m0 || !m1) return;
      var S = Math.min(ca.width, ca.height);
      var fs = Math.max(8.5, Math.min(14, S / 30));
      var lw = Math.max(1, S / 420);
      var xm = (m0.x + m1.x) / 2;

      // dashed liquid-range connector between the two bar tops
      if (emphasis === 'Both') {
        ctx.save();
        ctx.strokeStyle = '#3a3a3a';
        ctx.lineWidth = lw;
        ctx.setLineDash([3, 3]);
        ctx.beginPath(); ctx.moveTo(xm, m0.y); ctx.lineTo(xm, m1.y); ctx.stroke();
        ctx.setLineDash([]);
        var cap = Math.max(3, S * 0.012);
        ctx.beginPath(); ctx.moveTo(xm - cap, m0.y); ctx.lineTo(xm + cap, m0.y);
        ctx.moveTo(xm - cap, m1.y); ctx.lineTo(xm + cap, m1.y); ctx.stroke();
        ctx.restore();
      }

      var lines = ['C' + selected + ' \u00b7 ' + NAMES[i],
        'mp ' + fmt(MP[i]) + ' \u00b0C    bp ' + fmt(BP[i]) + ' \u00b0C'];
      if (emphasis === 'Both') lines.push('liquid range \u0394 = ' + fmt(BP[i] - MP[i]) + ' \u00b0C');

      ctx.save();
      ctx.font = fs + 'px sans-serif';
      var w = 0;
      for (var k = 0; k < lines.length; k++) w = Math.max(w, ctx.measureText(lines[k]).width);
      var padB = fs * 0.6;
      var bw = w + padB * 2, bh = lines.length * fs * 1.3 + padB * 1.4;

      var rects = barRects(chart);
      var L = legendMetrics(chart, ctx);
      var legendBox = { x0: L.x - 4, x1: L.x + L.w + 6, y0: L.y - 4, y1: L.y + L.h + 4 };
      rects.push(legendBox);

      var topOfPair = Math.min(m0.y, m1.y, m0.base);
      function clampX(x) { return Math.min(Math.max(x, ca.left + 5), ca.right - bw - 5); }
      function clampY(y) { return Math.min(Math.max(y, ca.top + 5), ca.bottom - bh - 5); }

      // candidate positions, in order of preference
      var cands = [
        { x: clampX(xm - bw / 2), y: topOfPair - fs * 1.5 - bh, leader: true },           // above the pair
        { x: ca.left + L.pad, y: legendBox.y1 + L.pad * 0.8, leader: false },              // under the legend
        { x: clampX(ca.left + ca.width * 0.30), y: clampY(ca.top + ca.height * 0.10), leader: false },
        { x: clampX(ca.left + ca.width * 0.06), y: clampY(ca.top + ca.height * 0.52), leader: false },
        { x: clampX(ca.right - bw - L.pad), y: clampY(ca.bottom - bh - L.pad), leader: false }
      ];

      var pick = null;
      for (var c = 0; c < cands.length; c++) {
        var q = cands[c];
        if (q.y < ca.top + 4 || q.y + bh > ca.bottom - 4) continue;
        var box = { x0: q.x - 3, x1: q.x + bw + 3, y0: q.y - 3, y1: q.y + bh + 3 };
        if (!hits(box, rects)) { pick = q; break; }
      }
      if (!pick) pick = { x: clampX(ca.left + ca.width * 0.30), y: clampY(ca.top + ca.height * 0.08), leader: false };

