      if (pick.leader) {
        ctx.strokeStyle = '#555'; ctx.lineWidth = lw;
        ctx.beginPath();
        ctx.moveTo(xm, by + bh); ctx.lineTo(xm, topOfPair - fs * 0.3); ctx.stroke();
        ctx.fillStyle = '#555';
        ctx.beginPath(); ctx.arc(xm, topOfPair - fs * 0.3, lw * 1.6, 0, Math.PI * 2); ctx.fill();
      }
      ctx.fillStyle = 'rgba(255,255,255,0.96)';
      ctx.strokeStyle = '#2b2b2b';
      ctx.lineWidth = lw;
      roundRect(ctx, bx, by, bw, bh, fs * 0.4);
      ctx.fill(); ctx.stroke();
      ctx.textBaseline = 'top';
